class Api:
    """All interfaces of one Gx connection."""

    def __init__(self, gx):
        self.project = Project(gx)
        self.communication = Communication(gx)
        self.product = Product(gx)
        self.transmitter = Transmitter(gx)
        self.session = Session(gx)
        self.view = View(gx)
